"use client";

import "../../styles/teum-base.css";
import "../../styles/components/avatar.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type AvatarProps = ComponentPropsWithRef<"span"> & {
  src?: string;
  alt?: string;
  fallback: string;
  size?: "small" | "medium" | "large";
  status?: "online" | "away" | "busy" | "offline";
};

function fallbackTone(value: string) {
  return [...value].reduce((total, character) => (total * 31 + (character.codePointAt(0) ?? 0)) >>> 0, 0) % 4;
}

export function Avatar({ className, src, alt = "", fallback, size = "medium", status, role, "aria-label": ariaLabel, ...props }: AvatarProps) {
  const fallbackLabel = (ariaLabel ?? alt) || undefined;

  return (
    <span
      className={cn("teum-avatar", `teum-avatar--${size}`, className)}
      data-status={status || undefined}
      data-tone={src ? undefined : fallbackTone(fallback)}
      role={src ? role : role ?? (fallbackLabel ? "img" : undefined)}
      aria-label={src ? ariaLabel : fallbackLabel}
      {...props}
    >
      {src ? <img src={src} alt={alt} /> : <span className="teum-avatar__fallback" aria-hidden="true">{fallback.slice(0, 2).toLocaleUpperCase()}</span>}
      {status && <span className="teum-avatar__status" data-status={status} role="img" aria-label={`${status} presence`} />}
    </span>
  );
}

export function AvatarGroup({ className, children, ...props }: ComponentPropsWithRef<"div">) {
  return <div role="group" className={cn("teum-avatar-group", className)} {...props}>{children}</div>;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-avatar {
  position: relative;
  display: inline-grid;
  flex: 0 0 auto;
  isolation: isolate;
  place-items: center;
  overflow: visible;
  border: 1px solid color-mix(in oklch, var(--teum-control-border) 82%, transparent);
  border-radius: 50%;
  background: var(--teum-gray-100);
  color: var(--teum-gray-700);
  box-shadow: 0 1px 2px rgb(17 17 19 / .045), inset 0 1px 0 rgb(255 255 255 / .5);
  font-weight: 620;
  letter-spacing: -0.035em;
}

.teum-avatar[data-tone="0"] { background: var(--teum-gray-50); }

.teum-avatar[data-tone="1"] { background: var(--teum-gray-100); }

.teum-avatar[data-tone="2"] { background: var(--teum-gray-200); color: var(--teum-gray-800); }

.teum-avatar[data-tone="3"] { border-color: var(--teum-gray-800); background: var(--teum-gray-800); color: var(--teum-gray-50); box-shadow: 0 1px 2px rgb(17 17 19 / .12), inset 0 1px 0 rgb(255 255 255 / .1); }

.teum-avatar img,
.teum-avatar__fallback { width: 100%; height: 100%; border-radius: inherit; object-fit: cover; display: grid; place-items: center; }

.teum-avatar__fallback { line-height: 1; text-align: center; transform: translateY(.25px); }

.teum-avatar__status { position: absolute; z-index: 2; right: -2px; bottom: -2px; width: 12px; height: 12px; border: 2px solid var(--teum-bg-canvas); border-radius: 50%; background: var(--teum-gray-700); box-shadow: 0 0 0 1px color-mix(in oklch, var(--teum-control-border) 70%, transparent); }

.teum-avatar__status[data-status="away"] { background: var(--teum-gray-400); }

.teum-avatar__status[data-status="busy"] { background: var(--teum-gray-900); }

.teum-avatar__status[data-status="offline"] { background: var(--teum-bg-control); box-shadow: inset 0 0 0 1px var(--teum-gray-400); }

.teum-avatar-group { display: flex; align-items: center; isolation: isolate; }

.teum-avatar-group .teum-avatar { box-shadow: 0 0 0 2px var(--teum-bg-canvas), 0 2px 5px rgb(17 17 19 / .06), inset 0 1px 0 rgb(255 255 255 / .48); }

.teum-avatar-group .teum-avatar + .teum-avatar { margin-left: -6px; }

.teum-avatar-group .teum-avatar[data-status] { z-index: 1; }
}
